-- ---------- notificaciones (mismos mensajes que NotificationListener)
INSERT INTO notifications (recipient_id, type, message, related_entity_id, is_read, created_at)
SELECT f.receiver_id, 'FRIEND_REQUEST_SENT', rq.name || ' te envió una solicitud de amistad', f.id,
       (f.status <> 'PENDING' OR f.created_at < LOCALTIMESTAMP - interval '4 days'), f.created_at
FROM friendships f
JOIN seed_friendships s ON s.id = f.id
JOIN users rq ON rq.id = f.requester_id
WHERE (SELECT go FROM seed_run);

INSERT INTO notifications (recipient_id, type, message, related_entity_id, is_read, created_at)
SELECT f.requester_id,
       CASE WHEN f.status = 'ACCEPTED' THEN 'FRIEND_REQUEST_ACCEPTED' ELSE 'FRIEND_REQUEST_REJECTED' END,
       rc.name || CASE WHEN f.status = 'ACCEPTED' THEN ' aceptó tu solicitud de amistad' ELSE ' rechazó tu solicitud de amistad' END,
       f.id, x.at < LOCALTIMESTAMP - interval '2 days', x.at
FROM friendships f
JOIN seed_friendships s ON s.id = f.id
JOIN users rc ON rc.id = f.receiver_id
CROSS JOIN LATERAL (SELECT LEAST(f.created_at + make_interval(hours => (f.id % 47)::int + 1), LOCALTIMESTAMP) AS at) x
WHERE f.status IN ('ACCEPTED', 'REJECTED') AND (SELECT go FROM seed_run);

INSERT INTO notifications (recipient_id, type, message, related_entity_id, is_read, created_at)
SELECT ag.user_id, 'MATCH_PROPOSED', pu.name || ' te propuso un match', m.id,
       (m.status <> 'PENDING' OR x.at < LOCALTIMESTAMP - interval '1 day'), x.at
FROM matches m
JOIN seed_matches s ON s.id = m.id
JOIN gaps pg ON pg.id = m.proposer_gap_id
JOIN gaps ag ON ag.id = m.acceptor_gap_id
JOIN users pu ON pu.id = pg.user_id
CROSS JOIN LATERAL (SELECT LEAST(m.start_time - make_interval(hours => (m.id % 70)::int + 2),
                                 LOCALTIMESTAMP - make_interval(mins => (m.id % 40)::int + 1)) AS at) x
WHERE (SELECT go FROM seed_run);

INSERT INTO notifications (recipient_id, type, message, related_entity_id, is_read, created_at)
SELECT pg.user_id,
       CASE WHEN m.status = 'REJECTED' THEN 'MATCH_REJECTED' ELSE 'MATCH_ACCEPTED' END,
       au.name || CASE WHEN m.status = 'REJECTED' THEN ' rechazó tu match' ELSE ' aceptó tu match' END,
       m.id, x.at < LOCALTIMESTAMP - interval '1 day', x.at
FROM matches m
JOIN seed_matches s ON s.id = m.id
JOIN gaps pg ON pg.id = m.proposer_gap_id
JOIN gaps ag ON ag.id = m.acceptor_gap_id
JOIN users au ON au.id = ag.user_id
CROSS JOIN LATERAL (SELECT LEAST(m.start_time - make_interval(hours => (m.id % 70)::int + 2)
                                 + make_interval(mins => (m.id % 300)::int + 10), LOCALTIMESTAMP) AS at) x
WHERE m.status IN ('ACCEPTED', 'COMPLETED', 'REJECTED') AND (SELECT go FROM seed_run);

INSERT INTO notifications (recipient_id, type, message, related_entity_id, is_read, created_at)
SELECT ot.creator_id, 'OPEN_TABLE_JOINED', u.name || ' se unió a tu open table "' || ot.title || '"', ot.id,
       p.joined_at < LOCALTIMESTAMP - interval '2 days', p.joined_at
FROM participants_open_tables p
JOIN seed_participants s ON s.id = p.id
JOIN open_tables ot ON ot.id = p.open_table_id
JOIN users u ON u.id = p.user_id
WHERE p.user_id <> ot.creator_id AND (SELECT go FROM seed_run);
